// Property page per type (#45, George 21/10/2026): house technical facts without the year,
// hotel facts for everyone without its name or website, no "(possibly generated by AI)" tail.
// Starts the stub API (127.0.0.1:4339) and the BUILT site (127.0.0.1:4331). Exit 1 on any FAIL.
// Usage (from apps/hp, after `pnpm build`): node scripts/test-property-types.mjs
import { spawn } from 'node:child_process';
import { startStub } from './stub-api.mjs';

const SITE = 'http://127.0.0.1:4331';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
const check = (name, ok, detail) => { if (!ok) fails++; console.log(`${ok ? 'OK  ' : 'FAIL'} ${name} — ${detail}`); };

const stub = await startStub({ port: 4339, n: 60, variety: true });
const site = spawn(process.execPath, ['dist/server/entry.mjs'], {
  env: { ...process.env, HOST: '127.0.0.1', PORT: '4331', EALIDA_API: stub.base, SITE_ENV: 'preview' },
});
for (let i = 0; i < 40; i++) { try { await fetch(SITE + '/robots.txt'); break; } catch { await sleep(250); } }

const page = async (path) => {
  const res = await fetch(SITE + path);
  const html = await res.text();
  return { status: res.status, html, text: html.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ') };
};
const fact = (text, label, value) => new RegExp(`${label}\\s+${value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`).test(text);

try {
  const house = await page('/en/property/10008');
  check('house page 200', house.status === 200, `status ${house.status}`);
  for (const [l, v] of [['Condition', 'Renovated'], ['Levels', '2'], ['Parking spaces', '2'], ['Storage room', 'Yes'],
    ['Heating', 'Heat pump · independent'], ['Drainage', 'Private treatment plant'], ['Furniture', 'Partly furnished'],
    ['Pool', 'Private, outdoor']]) {
    check(`house shows ${l}: ${v}`, fact(house.text, l, v), fact(house.text, l, v) ? 'found' : 'missing');
  }
  check('house: no construction year', !/1999/.test(house.text), /1999/.test(house.text) ? 'year printed' : 'absent');
  check('house: no AI tail in the description', !/generated by AI/i.test(house.html) && house.text.includes('Stone house above the bay.'),
    /generated by AI/i.test(house.html) ? 'tail still there' : 'clean');

  const el = await page('/' + encodeURIComponent('ακινητο') + '/10008');
  check('Greek house page shows «Ανακαινισμένο»', el.text.includes('Ανακαινισμένο'), el.text.includes('Ανακαινισμένο') ? 'found' : `status ${el.status}, missing`);

  const hotel = await page('/en/property/10013');
  check('hotel page 200 for a guest', hotel.status === 200, `status ${hotel.status}`);
  for (const [l, v] of [['Classification', '★★★★'], ['Rooms', '32'], ['Beds', '70'], ['Double rooms', '24'], ['Suites', '8'],
    ['Condition', 'Good condition'], ['Town plan', 'Within the plan']]) {
    check(`hotel shows ${l}: ${v}`, fact(hotel.text, l, v), fact(hotel.text, l, v) ? 'found' : 'missing');
  }
  check('hotel area from biz_sq_meters', /1,450\s*m²/.test(hotel.text), /1,450\s*m²/.test(hotel.text) ? 'found' : 'missing');
  check('hotel name and website never in the page', !/Stub Bay Hotel|stub-bay-hotel/i.test(hotel.html), 'absent');

  const land = await page('/en/property/10002');
  check('land keeps its own facts', fact(land.text, 'Buildable', 'Buildable') && !/Drainage|Heating/.test(land.text), 'land facts only');

  const { stripAiTail } = await import('../src/lib/property.ts');
  for (const [inp, out] of [
    ['A villa.(possibly generated by AI)', 'A villa.'],
    ['Μια βίλα. (ενδεχομένως δημιουργήθηκε από την AI)', 'Μια βίλα.'],
    ['Eine Villa. (möglicherweise durch KI generiert) ', 'Eine Villa.'],
    ['Вила. (Възможно е генериран от AI)', 'Вила.'],
    ['Close to the AI (Agios Ioannis) beach (2 km).', 'Close to the AI (Agios Ioannis) beach (2 km).'],
    ['A villa (with pool).', 'A villa (with pool).'],
  ]) check(`stripAiTail «${inp}»`, stripAiTail(inp) === out, stripAiTail(inp));
} finally {
  site.kill(); stub.server?.close?.(); stub.close?.();
}
console.log(fails ? `${fails} FAIL` : 'ALL OK');
process.exit(fails ? 1 : 0);
